import pathlib,sys,unittest
from unittest.mock import patch
sys.path.insert(0,str(pathlib.Path.cwd()/'scripts/perf'));sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
from gate_analysis import EXTRA_CHECKS,EXTRA_METRICS,summarize_csharp
class GateAnalysisTests(unittest.TestCase):
    def case(self,checks):
        result={'checks':checks,'valid':all(checks.values()),'metrics':{},'unavailable_checks':{},'unavailable_metrics':{}}
        with patch('gate_analysis.original_summarize',return_value=result):return summarize_csharp(None,None,None)
    def test_available_pass_does_not_claim_full_rust_equivalence(self):
        r=self.case({'scene_delivery':True});self.assertTrue(r['valid']);self.assertFalse(r['full_rust_gate_equivalence']);self.assertTrue(all(r['checks'][k] is None for k in EXTRA_CHECKS));self.assertTrue(all(r['metrics'][k] is None for k in EXTRA_METRICS))
    def test_receipt_failure_preserved(self):
        r=self.case({'scene_delivery':False});self.assertFalse(r['valid']);self.assertIs(r['checks']['scene_delivery'],False)
    def test_native_drop_failure_preserved(self):
        r=self.case({'zero_transport_drops':False});self.assertFalse(r['valid']);self.assertIs(r['checks']['zero_transport_drops'],False)
if __name__=='__main__':unittest.main()
